'use strict';
globalThis.SplitFormatProfiles=(()=>{
 const key='split.format-profiles.v1';let profiles=[];
 const valid=profile=>{if(!profile||typeof profile.name!=='string'||!profile.name.trim()||profile.name.length>60||!Array.isArray(profile.formats)||!profile.formats.length||profile.formats.length>100)return false;try{for(const f of profile.formats)validateDimensions(f.w,f.h);return true;}catch{return false;}};
 try{const stored=JSON.parse(localStorage.getItem(key)||'[]');if(Array.isArray(stored))profiles=stored.filter(valid).slice(0,100).map(p=>({name:p.name.trim(),formats:p.formats.map(f=>({w:f.w,h:f.h}))}));}catch{}
 const dimensions=()=>FORMATS.filter(f=>chosenFormats().includes(f.id)).map(f=>({w:f.w,h:f.h}));
 const signature=formats=>[...new Set(formats.map(f=>`${f.w}x${f.h}`))].sort().join(',');
 function persist(next){try{localStorage.setItem(key,JSON.stringify(next));profiles=next;render();return true;}catch{toast('Não foi possível salvar os perfis neste navegador.');return false;}}
 function render(){const holder=$('formatProfiles');holder.replaceChildren();const selected=signature(dimensions());for(const profile of profiles){const row=document.createElement('div');row.className='format-profile';const button=document.createElement('button');button.type='button';button.className='profile-activate';button.setAttribute('aria-pressed',String(selected===signature(profile.formats)));button.title=profile.formats.map(f=>`${f.w} × ${f.h}`).join(' · ');const name=document.createElement('span');name.textContent=profile.name;const count=document.createElement('small');count.textContent=`${profile.formats.length} tamanho${profile.formats.length===1?'':'s'}`;button.append(name,count);button.onclick=()=>activate(profile.name);const remove=document.createElement('button');remove.type='button';remove.className='icon-button profile-delete';remove.setAttribute('aria-label',`Excluir perfil ${profile.name}`);remove.title=`Excluir perfil ${profile.name}`;remove.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h16M9 7V4h6v3M6 7l1 13h10l1-13M10 10v7M14 10v7"/></svg>';remove.onclick=()=>drop(profile.name);row.append(button,remove);holder.append(row);}$('profileEmpty').hidden=profiles.length>0;}
 function save(name=$('formatProfileName').value){name=String(name).trim();const formats=dimensions();if(!name||name.length>60){toast('Dê um nome ao perfil, com até 60 caracteres.');return false;}if(!formats.length){toast('Selecione ao menos um tamanho para salvar o perfil.');return false;}if(formats.length>100){toast('Use até 100 tamanhos por perfil.');return false;}const index=profiles.findIndex(p=>p.name.toLocaleLowerCase('pt-BR')===name.toLocaleLowerCase('pt-BR'));if(index<0&&profiles.length>=100){toast('Você pode salvar até 100 perfis.');return false;}const next=clone(profiles),profile={name,formats};index<0?next.push(profile):next.splice(index,1,profile);if(!persist(next))return false;$('formatProfileName').value='';$('saveFormatProfileDetails').open=false;toast(index<0?'Perfil salvo neste navegador.':'Perfil atualizado com os tamanhos selecionados.');return true;}
 function activate(name){const profile=profiles.find(p=>p.name===name);if(!profile)return false;checkpoint();const checked=[];for(const size of profile.formats){let format=FORMATS.find(f=>f.w===size.w&&f.h===size.h);if(!format){format={id:`custom-${++customSequence}`,name:`Personalizado ${size.w} × ${size.h}`,...size,group:'CUSTOM',custom:true};FORMATS.push(format);}checked.push(format.id);}formatOptions([...new Set(checked)]);toast(`Perfil ${profile.name} selecionado. Clique em Gerar composições.`);return true;}
 function drop(name){const next=profiles.filter(p=>p.name!==name);if(next.length===profiles.length)return false;const previous=clone(profiles);if(!persist(next))return false;toast('Perfil excluído. Os formatos continuam disponíveis.');const undoButton=document.createElement('button');undoButton.type='button';undoButton.className='toast-undo';undoButton.textContent='Desfazer';undoButton.onclick=()=>{if(persist(previous))toast('Perfil restaurado.');};$('toast').append(undoButton);return true;}
 $('formatProfileForm').onsubmit=event=>{event.preventDefault();save();};render();return{save,activate,drop,render,list:()=>clone(profiles)};
})();
